const axios = require('axios');

async function convertVideoToMp3(url, format, quality, captchaToken) {
  try {
    const postResponse = await axios.post('https://api.ezsrv.net/api/convert', {
      url: url,
      format: format,
      quality: quality,
      captchaToken: captchaToken
    }, {
      headers: {
        'Content-Type': 'application/json'
      }
    });

    const jobId = postResponse.data.jobId;
    m.reply(`Konversi dimulai. Job ID: ${jobId}`);

    let status = 'processing';
    let downloadUrl = null;
    let title = null;

    while (status !== 'done') {
      await new Promise(resolve => setTimeout(resolve, 5000)); 
      const getResponse = await axios.get(`https://api.ezsrv.net/api/convert/status?jobId=${jobId}`);
      status = getResponse.data.status;
      downloadUrl = getResponse.data.downloadUrl;
      title = getResponse.data.title;

      if (status === 'done') {
        m.reply(`Konversi selesai! Judul: ${title}, URL Unduh: ${downloadUrl}`);
      } else {
        m.reply(`Status konversi: ${status}, Persentase: ${getResponse.data.percent}%`);
      }
    }
  } catch (error) {
    m.reply(`Terjadi kesalahan: ${error.message}`);
  }
}

